import React, { createContext, useContext, useState } from 'react';
import { getToggleGroupItemState, getToggleStyleKeys, toggleGroupStyleKeys, toggleValueInList } from '../lib/core';
import type { ToggleGroupBaseProps, ToggleGroupItemBaseProps } from '../lib/core';
import styles from './toggle-group.module.scss';

type ToggleGroupValue = string | string[];

interface ToggleGroupContextValue {
	type: 'single' | 'multiple';
	value: ToggleGroupValue;
	onItemClick: (itemValue: string) => void;
}

const ToggleGroupContext = createContext<ToggleGroupContextValue | null>(null);

function useToggleGroupContext(): ToggleGroupContextValue {
	const context = useContext(ToggleGroupContext);
	if (!context) {
		throw new Error('ToggleGroupItem must be used within <ToggleGroup>.');
	}
	return context;
}

export interface ToggleGroupProps extends React.HTMLAttributes<HTMLDivElement>, ToggleGroupBaseProps {
	value?: string | string[];
	defaultValue?: string | string[];
	onValueChange?: (value: string | string[]) => void;
}

const ToggleGroup = React.forwardRef<HTMLDivElement, ToggleGroupProps>(({ className = '', type = 'single', value, defaultValue, onValueChange, children, ...props }, ref) => {
	const [internalValue, setInternalValue] = useState<ToggleGroupValue>(defaultValue ?? (type === 'single' ? '' : []));
	const currentValue = value !== undefined ? value : internalValue;

	function handleItemClick(itemValue: string) {
		let next: ToggleGroupValue;

		if (type === 'single') {
			next = currentValue === itemValue ? '' : itemValue;
		} else {
			const list = Array.isArray(currentValue) ? currentValue : [];
			next = toggleValueInList(itemValue, list);
		}

		if (value === undefined) {
			setInternalValue(next);
		}

		onValueChange?.(next);
	}

	const context: ToggleGroupContextValue = { type, value: currentValue, onItemClick: handleItemClick };

	return (
		<ToggleGroupContext.Provider value={context}>
			<div ref={ref} role="group" data-slot="toggle-group" data-type={type} className={`${styles[toggleGroupStyleKeys.root]} ${className}`} {...props}>
				{children}
			</div>
		</ToggleGroupContext.Provider>
	);
});
ToggleGroup.displayName = 'ToggleGroup';

export interface ToggleGroupItemProps extends Omit<React.ButtonHTMLAttributes<HTMLButtonElement>, 'value'>, ToggleGroupItemBaseProps {}

const ToggleGroupItem = React.forwardRef<HTMLButtonElement, ToggleGroupItemProps>(
	({ className = '', value, variant = 'default', size = 'default', disabled, children, ...props }, ref) => {
		const context = useToggleGroupContext();
		const selected = context.type === 'single' ? context.value === value : Array.isArray(context.value) ? context.value.includes(value) : false;
		const state = getToggleGroupItemState(selected);
		const styleKeys = getToggleStyleKeys(variant, size);
		const classes = [styles[toggleGroupStyleKeys.item], styles[styleKeys.variant], styles[styleKeys.size], className].filter(Boolean).join(' ');

		return (
			<button
				ref={ref}
				type="button"
				value={value}
				aria-pressed={selected}
				data-state={state}
				data-active={selected}
				disabled={disabled}
				className={classes}
				{...props}
				onClick={() => context.onItemClick(value)}>
				{children}
			</button>
		);
	},
);
ToggleGroupItem.displayName = 'ToggleGroupItem';

export { ToggleGroup, ToggleGroupItem };
export default ToggleGroup;

@use '../../../styles/variables/colors' as *;

.root {
	display: inline-flex;
	width: fit-content;
	align-items: center;
	border-radius: var(--tile-toggle-group-radius, #{$radius});

	&[data-orientation='horizontal'] {
		> *:not(:first-child) {
			border-left: none;
			border-top-left-radius: 0;
			border-bottom-left-radius: 0;
		}

		> *:not(:last-child) {
			border-top-right-radius: 0;
			border-bottom-right-radius: 0;
		}
	}

	&[data-orientation='vertical'] {
		flex-direction: column;
		align-items: stretch;

		> *:not(:first-child) {
			border-top: none;
			border-top-left-radius: 0;
			border-top-right-radius: 0;
		}

		> *:not(:last-child) {
			border-bottom-right-radius: 0;
			border-bottom-left-radius: 0;
		}
	}
}

.item {
	display: inline-flex;
	align-items: center;
	justify-content: center;
	gap: var(--tile-toggle-group-gap, #{$spacing-2});
	white-space: nowrap;
	border-radius: var(--tile-toggle-group-radius, #{$radius});
	border: 1px solid transparent;
	font-size: var(--tile-toggle-group-font-size, #{$text-sm});
	line-height: var(--tile-toggle-group-line-height, inherit);
	font-weight: $font-medium;
	transition:
		color $transition-fast,
		background-color $transition-fast,
		border-color $transition-fast,
		box-shadow $transition-fast;
	outline: none;
	cursor: pointer;

	&:focus-visible {
		border-color: var(--tile-toggle-group-focus-border, #{$ring});
		box-shadow: var(--tile-toggle-group-focus-shadow, 0 0 0 3px color-mix(in srgb, #{$ring} 50%, transparent));
		z-index: 1;
	}

	&:disabled {
		pointer-events: none;
		opacity: 0.5;
		cursor: not-allowed;
	}

	svg {
		pointer-events: none;
		flex-shrink: 0;
		width: 1rem;
		height: 1rem;
	}

	// 状态
	&[data-state='on'] {
		background-color: var(--tile-toggle-group-selected-background, #{$accent});
		color: var(--tile-toggle-group-selected-color, #{$accent-foreground});
	}

	&[data-state='off'] {
		background-color: transparent;
		color: $foreground;

		&:hover:not(:disabled) {
			background-color: var(--tile-toggle-group-hover-background, #{$muted});
			color: var(--tile-toggle-group-hover-color, #{$muted-foreground});
		}
	}

	// 样式变体
	&.variantOutline {
		border-color: var(--tile-toggle-group-border, #{$border});
		box-shadow: var(--tile-toggle-group-shadow, #{$shadow-sm});
	}

	&.variantGhost {
		background-color: transparent;

		&[data-state='on'] {
			background-color: var(--tile-toggle-group-ghost-selected-background, #{$muted});
			color: var(--tile-toggle-group-ghost-selected-color, #{$muted-foreground});
		}
	}

	// 尺寸变体
	&.sizeDefault {
		height: var(--tile-toggle-group-height, 2.25rem);
		min-width: var(--tile-toggle-group-height, 2.25rem);
		padding: 0 var(--tile-toggle-group-padding-inline, #{$spacing-2});
	}

	&.sizeSm {
		height: var(--tile-toggle-group-sm-height, 2rem);
		min-width: var(--tile-toggle-group-sm-height, 2rem);
		padding: 0 var(--tile-toggle-group-sm-padding-inline, #{$spacing-1_5});
		font-size: var(--tile-toggle-group-sm-font-size, #{$text-sm});
		border-radius: var(--tile-toggle-group-sm-radius, #{$radius});
	}

	&.sizeLg {
		height: var(--tile-toggle-group-lg-height, 2.5rem);
		min-width: var(--tile-toggle-group-lg-height, 2.5rem);
		padding: 0 var(--tile-toggle-group-lg-padding-inline, #{$spacing-2_5});
	}
}
